/**
 * Every organization that has not been deleted, in a stable order. The
 * fleet-wide sweeps (overdue alerts, digest, retention) walk this list so no
 * tenant is ever left out, however many there are.
 */
export async function listLiveOrgIds(): Promise<readonly OrgId[]> {
  const rows = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(isNull(organizations.archivedAt))
    .orderBy(asc(organizations.id))
    .all();
